import RNA, random
target_block = "((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..))))"
cand = "GCGUACCGUAUCAACGUUUACCUCAUGGGCCCCAGGCGGUUUUCCCAUAGCUUUACAGCCAACGC"
print("cand len", len(cand), "target len", len(target_block))

comp = {'A':'U','U':'A','G':'C','C':'G'}

def bp_dist(ss,t):
    return RNA.bp_distance(ss,t)

best = cand
best_ss, _ = RNA.fold_compound(best).mfe()
best_d = bp_dist(best_ss, target_block)
print("start dist", best_d)
print("start ss ", best_ss)
print("target  ", target_block)

random.seed(1)
# focused hill climb on positions whose pairing differs
import itertools
# identify target pairs
stack=[]
pairs={}
for i,ch in enumerate(target_block):
    if ch=='(': stack.append(i)
    elif ch==')':
        op=stack.pop(); pairs[op]=i; pairs[i]=op

def diagnose(ss, t):
    # find missing pairs (in target not in ss) and spurious (in ss not in target)
    st=[]; ss_pairs={}
    for i,ch in enumerate(ss):
        if ch=='(': st.append(i)
        elif ch==')':
            if st:
              op=st.pop(); ss_pairs[op]=i; ss_pairs[i]=op
    missing=[]
    for i in range(len(t)):
        if i in pairs and i<pairs[i]:
            j=pairs[i]
            if ss[i] not in '()(' or i not in ss_pairs or ss_pairs[i]!=j:
                missing.append((i,j))
    spurious=[]
    for i in range(len(ss)):
        if i in ss_pairs and i<ss_pairs[i]:
            j=ss_pairs[i]
            if i not in pairs or pairs[i]!=j:
                spurious.append((i,j))
    return missing, spurious

# random restart hill climb
best_overall = best
best_overall_d = best_d
for restart in range(200):
    cur = list(best)
    # perturb: at missing/spurious pair positions, randomize to complementary pair or mismatch
    if restart>0:
        ss,_=RNA.fold_compound(''.join(cur)).mfe()
        miss, spur = diagnose(ss, target_block)
        for (i,j) in miss+spur:
            if random.random()<0.5:
                # set as strong GC pair
                cur[i]='G'; cur[j]='C'
            else:
                # AU pair
                cur[i]='A'; cur[j]='U'
        # also random mutate a couple random positions
        for _ in range(3):
            p=random.randrange(len(cur)); cur[p]=random.choice('ACGU')
    s=''.join(cur)
    ss,_=RNA.fold_compound(s).mfe()
    d=bp_dist(ss,target_block)
    # local greedy
    improved=True
    while improved:
        improved=False
        for i in range(len(s)):
            for b in 'ACGU':
                if b==cur[i]: continue
                nb=list(cur); nb[i]=b; ns=''.join(nb)
                nss,_=RNA.fold_compound(ns).mfe()
                nd=bp_dist(nss,target_block)
                if nd<d:
                    d=nd; cur=nb; s=ns; ss=nss; improved=True
    if d<best_overall_d:
        best_overall_d=d; best_overall=s
        print("restart",restart,"dist",d)
        if d==0:
            print("SOLVED:", s); break
print("BEST dist", best_overall_d)
print("BEST", best_overall)
ss,_=RNA.fold_compound(best_overall).mfe()
print("best ss", ss)
print("target  ", target_block)
